stage_templates.yaml_skeleton:
- name: Deploy over SSH
  uses: appleboy/ssh-action@v1
  with:
    host: {{secret.ssh_host}}
    username: {{secret.ssh_user}}
    key: {{secret.ssh_private_key}}
    script: |
      cd {{remote_app_path}}
      git pull origin {{branch}}
      npm ci --production
      pm2 restart {{app_name}} || pm2 start {{entry_file}} --name {{app_name}}

- name: Deploy to Kubernetes
  run: |
    echo "{{secret.kubeconfig}}" | base64 -d > kubeconfig.yaml
    export KUBECONFIG=kubeconfig.yaml
    kubectl set image deployment/{{deployment_name}} {{container_name}}={{image_ref}}
    kubectl rollout status deployment/{{deployment_name}}

- name: Slack notification
  if: always()
  uses: slackapi/slack-github-action@v1
  with:
    webhook: {{secret.slack_webhook_url}}
    webhook-type: incoming-webhook
    payload: |
      { "text": "Pipeline ${{ job.status }} for {{repo_name}} on {{branch}}" }
